package ledger

type Ledger struct{ Balance int }

func (l *Ledger) debit(amount int) bool {
	if amount < 0 || l.Balance <= amount {
		return false
	}
	l.Balance -= amount
	return true
}
</parameter>
<parameter=new_text>
package ledger

type Ledger struct{ Balance int }

func (l *Ledger) debit(amount int) bool {
	if amount < 0 || l.Balance < amount {
		return false
	}
	l.Balance -= amount
	return true
}
